import { describe, it } from "vitest";
import assert from "node:assert/strict";
import { ProjectSandbox } from "../../src/server/agent/project-sandbox.js";
import type { Component } from "../../src/server/agent/project-config-store.js";

type ExecCall = {
	containerId: string;
	args: string[];
	opts?: { cwd?: string; env?: Record<string, string>; timeout?: number };
};

function makeSandboxRecorder(configuredBaseRef: string | undefined = "origin/main"): { sandbox: ProjectSandbox; calls: ExecCall[] } {
	const sandbox = new ProjectSandbox({
		projectId: "sandbox-local-only-test",
		projectDir: "/host/project",
		repoUrl: "https://example.invalid/repo.git",
		image: "bobbit-test-image",
		baseRefResolver: () => configuredBaseRef,
	});
	const calls: ExecCall[] = [];
	type RepositoryState = {
		commonDir: string;
		branches: Set<string>;
		upstreams: Map<string, string>;
		worktrees: Map<string, { branch: string }>;
	};
	const repositories = new Map<string, RepositoryState>();
	const worktreeOwners = new Map<string, RepositoryState>();
	const repositoryForCwd = (cwd: string): RepositoryState => {
		const owner = worktreeOwners.get(cwd);
		if (owner) return owner;
		let repository = repositories.get(cwd);
		if (!repository) {
			repository = {
				commonDir: `${cwd}/.git`,
				branches: new Set(["main"]),
				upstreams: new Map([["main", "origin/main"]]),
				worktrees: new Map([[cwd, { branch: "main" }]]),
			};
			repositories.set(cwd, repository);
			worktreeOwners.set(cwd, repository);
		}
		return repository;
	};
	(sandbox as any).containerId = "container-local-only";
	(sandbox as any)._dockerExec = async (
		containerId: string,
		args: string[],
		opts?: { cwd?: string; env?: Record<string, string>; timeout?: number },
	): Promise<string> => {
		calls.push({ containerId, args: [...args], opts });
		const cwd = opts?.cwd;

		if (args[0] !== "git") return "";
		if (!cwd) throw new Error("missing git cwd");
		const repository = repositoryForCwd(cwd);
		const worktree = repository.worktrees.get(cwd);
		if (args[1] === "show-ref") {
			const branch = args.at(-1)?.replace("refs/heads/", "");
			if (branch && repository.branches.has(branch)) return "";
			throw new Error(`missing branch: ${branch ?? "unknown"}`);
		}
		if (args[1] === "worktree" && args[2] === "add") {
			const newBranch = args.indexOf("-b");
			const branch = newBranch >= 0 ? args[newBranch + 1] : args[4];
			const worktreePath = newBranch >= 0 ? args[newBranch + 2] : args[3];
			const startPoint = newBranch >= 0 ? args[newBranch + 3] : undefined;
			repository.branches.add(branch);
			if (!args.includes("--no-track") && startPoint?.startsWith("origin/")) {
				repository.upstreams.set(branch, startPoint);
			}
			repository.worktrees.set(worktreePath, { branch });
			worktreeOwners.set(worktreePath, repository);
			return "";
		}
		if (args[1] === "worktree" && args[2] === "list" && args.includes("--porcelain")) {
			return [...repository.worktrees.entries()]
				.map(([path, entry]) => `worktree ${path}\nHEAD deadbeef\nbranch refs/heads/${entry.branch}\n`)
				.join("\n");
		}
		if (args[1] === "branch" && args[2]?.startsWith("--set-upstream-to=")) {
			repository.upstreams.set(args[3], args[2].slice("--set-upstream-to=".length));
			return "";
		}
		if (args[1] === "rev-parse" && args.includes("--show-toplevel")) {
			if (worktree) return cwd;
			throw new Error(`missing worktree: ${cwd}`);
		}
		if (args[1] === "rev-parse" && args.includes("--abbrev-ref") && args.at(-1) === "HEAD") {
			if (worktree) return worktree.branch;
			throw new Error(`missing worktree: ${cwd}`);
		}
		if (args[1] === "rev-parse" && args.includes("--symbolic-full-name")) {
			const branch = args.at(-1)?.replace(/@\{upstream\}$/, "");
			const upstream = branch ? repository.upstreams.get(branch) : undefined;
			if (upstream) return upstream;
			throw new Error(`missing upstream: ${branch ?? "unknown"}`);
		}
		if (args[1] === "rev-parse" && args.includes("--git-common-dir")) return repository.commonDir;
		return "";
	};
	return { sandbox, calls };
}

function assertNoSandboxAutoPublish(calls: ExecCall[]): void {
	const rendered = calls.map(call => `${call.opts?.cwd ?? ""} $ ${call.args.join(" ")}`);
	const pushCommands = rendered.filter(command => /\bgit\s+push\b/.test(command));
	const hookCommands = rendered.filter(command => command.includes("post-commit") || command.includes("git rev-parse --git-dir"));
	assert.deepEqual(pushCommands, [], "sandbox worktree creation must not publish with git push");
	assert.deepEqual(hookCommands, [], "sandbox worktree creation must not install a post-commit hook");
}

describe("ProjectSandbox local-only worktrees", () => {
	it("createWorktree does not install a post-commit hook or publish the branch", async () => {
		const { sandbox, calls } = makeSandboxRecorder();

		const worktreePath = await sandbox.createWorktree("session/local-only", "session/local-only", "HEAD");

		assert.equal(worktreePath, "/workspace-wt/session/local-only");
		assert.ok(
			calls.some(call => call.args.join(" ") === "git worktree add --no-track -b session/local-only /workspace-wt/session/local-only HEAD"),
			"expected createWorktree to create the container worktree without implicit tracking",
		);
		assert.ok(
			calls.some(call => call.args.join(" ") === "git branch --set-upstream-to=origin/main session/local-only"),
			"expected createWorktree to validate and explicitly configure the base upstream",
		);
		assertNoSandboxAutoPublish(calls);
	});

	it("preserves Git's implicit remote upstream when no base ref is configured", async () => {
		const { sandbox, calls } = makeSandboxRecorder("");

		await sandbox.createWorktree("session/fallback", "session/fallback", "origin/main");

		assert.ok(
			calls.some(call => call.args.join(" ") === "git worktree add -b session/fallback /workspace-wt/session/fallback origin/main"),
			"expected remote fallback creation to retain Git's implicit tracking behavior",
		);
		assert.ok(
			!calls.some(call => call.args.includes("--no-track")),
			"expected no --no-track when no configured base requires explicit tracking",
		);
		assert.ok(
			!calls.some(call => call.args[1] === "branch" && call.args[2]?.startsWith("--set-upstream-to=")),
			"expected no explicit upstream mutation when Git supplies the fallback upstream",
		);
	});

	it("createWorktreeSet does not install post-commit hooks or publish repo worktree branches", async () => {
		const { sandbox, calls } = makeSandboxRecorder();
		const components: Component[] = [
			{ name: "api", repo: "services/api" },
			{ name: "web", repo: "apps/web" },
		];

		const result = await sandbox.createWorktreeSet("team/local-only", "team/local-only", components, "HEAD");

		assert.equal(result.container, "/workspace-wt/team/local-only");
		assert.deepEqual(result.worktrees, [
			{ repo: "services/api", worktreePath: "/workspace-wt/team/local-only/services/api" },
			{ repo: "apps/web", worktreePath: "/workspace-wt/team/local-only/apps/web" },
		]);
		assert.ok(
			calls.some(call => call.args.join(" ") === "git worktree add --no-track -b team/local-only /workspace-wt/team/local-only/services/api HEAD"),
			"expected createWorktreeSet to create the first repo worktree without implicit tracking",
		);
		assert.ok(
			calls.some(call => call.args.join(" ") === "git worktree add --no-track -b team/local-only /workspace-wt/team/local-only/apps/web HEAD"),
			"expected createWorktreeSet to create the second repo worktree without implicit tracking",
		);
		assert.ok(
			calls.filter(call => call.args.join(" ") === "git branch --set-upstream-to=origin/main team/local-only").length === 2,
			"expected each repo branch to validate and explicitly configure the base upstream",
		);
		assertNoSandboxAutoPublish(calls);
	});
});
